<Card class="w-full max-w-sm">
  <CardHeader>
    <CardTitle>Notifications</CardTitle>
    <CardDescription>You have 3 unread messages.</CardDescription>
    <CardAction>
      <Button type="button" variant="ghost" size="sm">Mark all read</Button>
    </CardAction>
  </CardHeader>
  <CardContent>
    <p>Your teammate commented on the "Q3 Roadmap" document.</p>
  </CardContent>
</Card>

